CREATE COLUMN TABLE "TEST_AP"."ORST" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(50) NOT NULL , "Desc" NVARCHAR(100), "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "LogInstanc" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ORST_SECONDARY" ON "TEST_AP"."ORST" ( "Code" ASC )